function renderCategory(c, depth = 3) {
  const hashes = "#".repeat(depth);
  const lines = [
    `${hashes} ${c.number}. ${c.name}`,
    "",
    c.summary,
    ""
  ];
  for (const sub of c.subCategories) {
    lines.push(`- **${sub.code} ${sub.name}** — ${sub.description}`);
  }
  return lines.join("\n");
}
__name(renderCategory, "renderCategory");
function getTaxonomyText(start, end, depth = 3) {
  return ERROR_TAXONOMY.filter((c) => c.number >= start && c.number <= end).map((c) => renderCategory(c, depth)).join("\n\n");
}
